      'hero_btn' => 'आमच्या टीमशी बोला',
      'scale_title' => 'स्केलिंग अंमलबजावणीद्वारे मर्यादित आहे.',
      'scale_p1' => 'व्यवसाय स्केलिंग करणे क्वचितच कल्पनांनी मर्यादित असते — ते अंमलबजावणीद्वारे मर्यादित असते. व्यवसाय क्षेत्र, उत्पादने आणि ग्राहक विभागांमध्ये विस्तारत असताना, विक्री, लोक आणि ऑन-ग्राउंड ऑपरेशन्स व्यवस्थापित करणे अधिक जटिल होत जाते.',
      'scale_p2' => 'बिसानी ब्रदर्समध्ये, आम्ही अंमलबजावणीची मालकी घेण्यासाठी संस्थांशी भागीदारी करतो — आम्ही तेथे पोहोचण्यासाठी आवश्यक संघ, प्रक्रिया आणि वितरण व्यवस्थापित करत असताना त्यांना वाढीवर लक्ष केंद्रित करण्यात मदत करतो.',
