      'svc2_d' => 'ऑन-ग्राउंड डेटा संकलन आणि बाजार अंतर्दृष्टी जे व्यवसायांना ग्राहकांना समजून घेण्यास, संधींचे प्रमाणीकरण करण्यात आणि निर्णय घेण्यास मदत करतात.',
