      'hero_desc' => 'வ struktured sales execution வாடிக்கை acquisition, merchant onboarding மற்றும் regional scale-க்கு உதவுகிறது.',
      'intro_title' => 'வாய்ப்புகளை முடிவுகளாக மாற்றுதல்',
      'intro_desc' => 'எங்கள் விற்பனை மற்றும் வளர்ச்சி தீர்வுகள் வணிகங்கள் வாய்ப்புகளை அளவிடக்கூடிய முடிவுகளாக மாற்ற உதவும் வகையில் வடிவமைக்கப்பட்டுள்ளன. பயிற்சியளிக்கப்பட்ட களக் குழுக்கள், கட்டமைக்கப்பட்ட செயல்முறைகள் மற்றும் நிகழ்நேர அறிக்கையிடல் ஆகியவற்றை இணைப்பதன் மூலம், FinTech, BFSI, கடன் வழங்குதல் மற்றும் அதனுடன் தொடர்புடைய துறைகளில் வளர்ச்சியை நாங்கள் செலுத்துகிறோம், உங்கள் லட்சியங்களுக்கு ஏற்ப செயல்திறனை உறுதிப்படுத்துகிறோம்.',
