      'hero_h1_a' => 'சந்தைகளைப் புரிந்துகொள்வது.',
      'hero_h1_b' => 'முடிவுகளைத் தெரிவிக்கவும்.',
      'hero_desc' => 'செயல்படக்கூடிய நுண்ணறிவு தரையில் இருந்து நேரடியாக சேகரிக்கப்பட்டது.',
      'intro_title' => 'நிஜ உலக உள்ளீடுகள். மூலோபாய நுண்ணறிவு.',
      'intro_desc' => 'எங்கள் கணக்கெடுப்பு மற்றும் சந்தை ஆராய்ச்சி தீர்வுகள், வணிகங்கள் நம்பிக்கையான முடிவுகளை எடுக்க உதவும் துல்லியமான, நிலத்தடித் தரவை வழங்குகின்றன.',
      'intro_highlight' => 'கணக்கெடுப்பு & சந்தை ஆராய்ச்சி',
      'c1_title' => 'வரையறுக்கப்பட்ட பார்வை',
      'c1_desc' => 'இலக்கு சந்தைகளில் வாடிக்கையாளர் விருப்பத்தேர்வுகள் மற்றும் போட்டியாளர் செயல்பாடுகளில் வரையறுக்கப்பட்ட தெரிவுநிலை.',
      'c2_title' => 'தரவு இடைவெளிகள்',
      'c2_desc' => 'மேசை ஆராய்ச்சிக்கும் உத்தியைப் பாதிக்கும் உண்மையான நிலத்தடி உண்மைகளுக்கும் இடையிலான இடைவெளிகள்.',
      'c3_title' => 'சரிபார்ப்பு சிக்கல்கள்',
      'c3_desc' => 'பெரிய முதலீடுகள் அல்லது வெளியீடுகளுக்கு முன் அனுமானங்களை சரிபார்ப்பதில் சிரமம்.',
      'c4_title' => 'சீரற்ற தரவு',
      'c4_desc' => 'முடிவின் தரம் மற்றும் வேகத்தை பாதிக்கும் சீரற்ற தரவு சேகரிப்பு.',
      'deliver_desc' => 'துல்லியமான, கட்டமைக்கப்பட்ட தரவைச் சேகரிக்க பயிற்சியளிக்கப்பட்ட களக் குழுக்களை நாங்கள் பயன்படுத்துகிறோம், உங்கள் சந்தை நிலப்பரப்பின் முழுப் படத்தைப் பெறுவதை உறுதிசெய்கிறோம்.',
      'd1' => 'நுகர்வோர் மற்றும் வணிகர் ஆய்வுகள்',
      'd2' => 'சந்தை மற்றும் பிராந்திய மதிப்பீடுகள்',
      'd3' => 'தயாரிப்பு கருத்து மற்றும் மாதிரி ஆய்வுகள்',
      'd4' => 'கட்டமைக்கப்பட்ட அறிக்கையிடலுடன் தரவு சேகரிப்பு',
      'form_build_title' => 'தரவை முடிவுகளாக மாற்றவும்',
    ),
    'staffing-solutions' => 
    array (
      'hero_h1_a' => 'சரியான மக்கள்.',
      'hero_h1_b' => 'நோக்கத்துடன் பயன்படுத்தப்பட்டது.',
      'hero_desc' => 'உங்கள் வணிகத் தேவைகளுக்கு ஏற்ப அளவிடக்கூடிய பணியாளர் தீர்வுகள்.',
      'intro_title' => 'திறமையுடன் கூடிய திறமை',
      'intro_desc' => 'எங்கள் பணியாளர் தீர்வுகள், கள விற்பனை, செயல்பாடுகள் மற்றும் விரிவாக்கத் திட்டங்களுக்கு பயிற்சியளிக்கப்பட்ட, வரிசைப்படுத்த-தயாரான குழுக்களை வழங்குகின்றன.',
      'intro_highlight' => 'பணியாளர் தீர்வுகள்',
      'c1_title' => 'ஆதார சிரமம்',
      'c1_desc' => 'பல நகரங்களில் தகுதிவாய்ந்த புலத் திறமைகளை ஆதாரமாகக் கொள்வதில் சிரமம்.',
      'c2_title' => 'உயர் தேய்வு',
      'c2_desc' => 'முக்கியமான திட்டங்களின் தொடர்ச்சியையும் செயல்திறனையும் பாதிக்கும் உயர் தேய்வு.',
      'c3_title' => 'அளவிடுதல் வேகம்',
      'c3_desc' => 'திட்ட காலக்கெடுக்கள் விரைவான குழு வரிசைப்படுத்தலைக் கோரும் போது மெதுவாக அணிதிரட்டல்.',
      'c4_title' => 'தரக் கட்டுப்பாடு',
      'c4_desc' => 'விநியோகிக்கப்பட்ட அணிகள் முழுவதும் சீரற்ற தரம் மற்றும் பயிற்சி தரநிலைகள்.',
      'deliver_desc' => 'உங்கள் செயல்பாடுகள் ஒரு போதும் தவறாமல் இருப்பதை உறுதிசெய்யும் விரிவான பணியாளர் தீர்வுகளை நாங்கள் வழங்குகிறோம்.',
      'd1' => 'தொழிற்துறைகள் முழுவதும் பயிற்சி பெற்ற மனிதவள வரிசைப்படுத்தல்',
      'd2' => 'விற்பனை, செயல்பாடுகள் மற்றும் ஆதரவு ஊழியர்கள்',
      'd3' => 'நெகிழ்வான பணியாளர் மாதிரிகள் (குறுகிய மற்றும் நீண்ட கால)',
      'd4' => 'மையப்படுத்தப்பட்ட ஒருங்கிணைப்பு மற்றும் செயல்திறன் கண்காணிப்பு',
      'form_build_title' => 'BBPL உடன் உங்கள் குழுவை உருவாக்குங்கள்',
    ),
    'btl-atl' => 
    array (
      'hero_h1_a' => 'பார்வையை உருவாக்குதல்.',
      'hero_h1_b' => 'டிரைவிங் ஈடுபாடு.',
      'hero_desc' => 'பார்வையாளர்களுடன் இணைக்கும் ஆன்-கிரவுண்ட் பிராண்ட் எக்ஸிகியூஷன்.',
      'intro_title' => 'பிராண்டுகளை பார்வையாளர்களுடன் இணைத்தல்',
      'intro_desc' => 'எங்களின் BTL & ATL ஆக்டிவேஷன் சேவைகள் மறக்கமுடியாத பிராண்ட் அனுபவங்களையும், நிலத்தடி தாக்கத்தையும் உருவாக்குகின்றன.',
      'intro_highlight' => 'BTL & ATL செயல்படுத்தல்',
      'c1_title' => 'குறைந்த பார்வை',
      'c1_desc' => 'நெரிசலான உள்ளூர் சந்தைகளில் தெரிவுநிலையை அடைய பிராண்டுகள் போராடுகின்றன.',
      'c2_title' => 'சீரற்ற செயல்படுத்தல்',
      'c2_desc' => 'நிலையான செயல்முறைகள் இல்லாமல் எல்லா இடங்களிலும் பிரச்சார இயக்கம் மாறுபடும்.',
      'c3_title' => 'நிச்சயதார்த்த சிக்கல்கள்',
      'c3_desc' => 'குறிப்பிடத்தக்க விளம்பரச் செலவுகள் இருந்தபோதிலும் குறைந்த பார்வையாளர்களின் ஈடுபாடு.',
      'c4_title' => 'அளவிடப்படாத தாக்கம்',
      'c4_desc' => 'ROI மற்றும் ஆன்-கிரவுண்ட் பிரச்சாரத்தின் செயல்திறனை அளவிடுவதில் சிரமம்.',
      'deliver_desc' => 'அறிமுகம் முதல் கடைசி மைல் தாக்கம் வரை, உங்கள் பிராண்டின் உடல் இருப்பின் ஒவ்வொரு அம்சத்தையும் நாங்கள் நிர்வகிக்கிறோம்.',
      'd1' => 'தயாரிப்பு வெளியீடுகள் மற்றும் பிராண்ட் செயல்படுத்தல்கள்',
      'd2' => 'மாதிரி மற்றும் விளம்பர பிரச்சாரங்கள்',
      'd3' => 'சில்லறை விற்பனை மற்றும் கால்-ஆன்-தெரு நடவடிக்கைகள்',
      'd4' => 'கட்டமைக்கப்பட்ட அறிக்கையிடலுடன் பிரச்சாரத்தை செயல்படுத்துதல்',
      'form_build_title' => 'உங்கள் அடுத்த செயல்பாட்டைத் திட்டமிடுங்கள்',
    ),
    'lending-collection' => 
    array (
      'hero_h1_a' => 'நிதி உதவி',
      'hero_h1_b' => 'பொறுப்புடன் பயணங்கள்.',
      'hero_desc' => 'கட்டமைக்கப்பட்ட கடன் விற்பனை மற்றும் வசூல் செயல்படுத்தல்.',
      'intro_title' => 'வெளிப்படைத்தன்மை, இணக்கம், செயல்திறன்',
      'intro_desc' => 'எங்கள் லெண்டிங் & கலெக்ஷன்ஸ் சொல்யூஷன்ஸ் NBFCகள் மற்றும் FinTech ஆகியவற்றை ஒழுக்கமான களக் குழுக்கள் மற்றும் இணக்கமான வாடிக்கையாளர் ஈடுபாட்டுடன் ஆதரிக்கிறது.',
      'intro_highlight' => 'கடன் மற்றும் சேகரிப்பு தீர்வுகள்',
      'c1_title' => 'திறமையான அளவிடுதல்',
      'c1_desc' => 'தரமான தரங்களைப் பேணும்போது சேகரிப்பு மற்றும் விற்பனைக் குழுக்களை அளவிடுதல்.',
      'c2_title' => 'இணக்கம் & நெறிமுறைகள்',
      'c2_desc' => 'பிராந்தியங்கள் முழுவதும் இணக்கமான, நெறிமுறை வாடிக்கையாளர் தொடர்புகளை உறுதி செய்தல்.',
      'c3_title' => 'தகவல் தொடர்பு தரம்',
      'c3_desc' => 'கடனாளிகளின் சீரற்ற தொடர்பு, மீட்பு விகிதங்களை பாதிக்கிறது.',
      'c4_title' => 'செயல்திறன் கண்காணிப்பு',
      'c4_desc' => 'களக் குழு செயல்திறன் மற்றும் விளைவுகளில் வரம்புக்குட்பட்ட பார்வை.',
      'deliver_desc' => 'பயிற்சி பெற்ற ஆதரவு மற்றும் நெறிமுறை செயல்பாட்டின் மூலம் நிதி நிறுவனங்களுக்கும் வாடிக்கையாளர்களுக்கும் இடையே உள்ள இடைவெளியை நாங்கள் குறைக்கிறோம்.',
      'd1' => 'கடன் தயாரிப்பு விற்பனை ஆதரவு',
      'd2' => 'பிரத்யேக கால் சென்டர் செயல்பாடுகள்',
      'd3' => 'களம் மற்றும் தொலைத்தொடர்பு உதவி',
      'd4' => 'கட்டமைக்கப்பட்ட அறிக்கையிடல் மற்றும் இணக்கம்-தலைமையிலான செயல்படுத்தல்',
      'form_build_title' => 'உங்கள் கடன் ஆதரவு தேவைகளைப் பற்றி விவாதிக்கவும்',
    ),
    'ev-infrastructure' => 
    array (
      'hero_h1_a' => 'EV விரிவாக்கத்தை ஆற்றுகிறது.',
      'hero_h1_b' => 'ஆன்-கிரவுண்ட் எக்ஸிகியூஷன்.',
      'hero_desc' => 'சார்ஜிங் நெட்வொர்க்குகளை திறம்பட அளவிடுவதற்கு இருப்பிட அடையாளம், பார்ட்னர் ஆன்போர்டிங் மற்றும் ரோல்அவுட் ஒருங்கிணைப்புடன் EV உள்கட்டமைப்பு நிறுவனங்களை நாங்கள் ஆதரிக்கிறோம்.',
      'intro_title' => 'உங்கள் சார்ஜிங் நெட்வொர்க் வரிசைப்படுத்தலை விரைவுபடுத்துங்கள்',
      'intro_desc' => 'எங்கள் EV உள்கட்டமைப்பு ரோல்அவுட் ஆதரவு நிறுவனங்கள் இருப்பிடங்களை அடையாளம் காணவும், உள் கூட்டாளர்களை அடையாளம் காணவும் மற்றும் பல நகர விரிவாக்கத்தை ஒருங்கிணைக்கவும் உதவுகிறது.',
      'intro_highlight' => 'EV உள்கட்டமைப்பு ரோல்அவுட் ஆதரவு',
      'c1_title' => 'இடம் சாத்தியம்',
      'c1_desc' => 'சாத்தியமான சார்ஜிங் இடங்களை சரியான கவனத்துடன் கண்டறிதல்.',
      'c2_title' => 'கூட்டாளர் சீரமைப்பு',
      'c2_desc' => 'சுமூகமான வெளியீடுகளுக்காக உள்ளூர் கூட்டாளர்களை உள்வாங்குதல் மற்றும் சீரமைத்தல்.',
      'c3_title' => 'செயல்படுத்தல் இடைவெளிகள்',
      'c3_desc' => 'திட்டமிடல் மற்றும் தரையில் நிறுவல் காலவரிசைகளுக்கு இடையே உள்ள இடைவெளிகள்.',
      'c4_title' => 'பல நகர சிக்கலானது',
