    'partner-with-us' => 
    array (
      'hero_title' => 'எங்களுடன் கூட்டாளர்',
      'hero_desc' => 'உண்மையான திட்டங்களுடன் வளரத் தயாராக இருக்கும் தனிநபர்கள் மற்றும் குழுக்களுக்காக உருவாக்கப்படும் வாய்ப்புகள்.',
      'hero_btn' => 'திட்டப்பணிகளுக்கு விண்ணப்பிக்கவும்',
      'intro_p1' => 'பிசானி பிரதர்ஸில், தனிநபர்கள், ஏஜென்சிகள் மற்றும் குழுக்கள் இந்தியா முழுவதும் பெரிய அளவிலான வணிகச் செயலாக்கத் திட்டங்களில் பங்கேற்க கட்டமைக்கப்பட்ட வேலை வாய்ப்புகளை உருவாக்குகிறோம்.',
      'intro_p2' => 'நீங்கள் ஒரு சுயாதீனமான நிபுணராக இருந்தாலும் அல்லது நிலத்தடி பணியாளர்களைக் கொண்ட நிறுவனமாக இருந்தாலும் சரி, நிலையான திட்டங்கள், தெளிவான செயல்முறைகள் மற்றும் நம்பகமான ஈடுபாட்டிற்கான அணுகலை நாங்கள் வழங்குகிறோம் - வணிகங்களை விரிவுபடுத்துவதன் மூலம் நீங்கள் சம்பாதிக்கவும், கற்றுக்கொள்ளவும் மற்றும் வளரவும் உதவுகிறது.',
      'intro_p3' => 'ஏற்கனவே எங்களுடன் தொடர்புடைய 2,100+ நபர்களுடன், எங்கள் நெட்வொர்க் நம்பிக்கை, செயல்படுத்தல் மற்றும் நீண்ட கால ஒத்துழைப்பு ஆகியவற்றின் அடிப்படையில் கட்டமைக்கப்பட்டுள்ளது.',
      'opp_title' => 'நீங்கள் வேலை செய்யக்கூடிய வாய்ப்புகள்',
      'opp_subtitle' => 'நாங்கள் பரந்த அளவிலான ஆன்-கிரவுண்ட் மற்றும் ஃபீல்ட் எக்ஸிகியூஷன் திட்டங்களில் கூட்டாளர்களை ஈடுபடுத்துகிறோம், அவற்றுள்:',
      'opp1' => 'விற்பனை மற்றும் வணிகர் சேர்க்கை முயற்சிகள்',
      'opp2' => 'சந்தை ஆய்வுகள், தணிக்கைகள் மற்றும் வாடிக்கையாளர் சரிபார்ப்பு',
      'opp3' => 'புலம் செயல்படுத்துதல் மற்றும் பிராண்ட் அவுட்ரீச் திட்டங்கள்',
      'opp4' => 'கடன் ஆதரவு, ஆவணங்கள் மற்றும் சேகரிப்பு உதவி',
      'opp5' => 'பிராந்திய விரிவாக்கம் மற்றும் முன்னோடி சந்தை திட்டங்கள்',
      'opp_closing' => 'வாய்ப்புகள் பிராந்தியம், அளவு மற்றும் கால அளவைப் பொறுத்து மாறுபடும் - தனிநபர்கள் மற்றும் ஏஜென்சிகள் இருவரும் தங்கள் திறனுடன் சீரமைக்கப்பட்ட வேலையைக் கண்டறிய அனுமதிக்கிறது.',
      'offer_title' => 'நாங்கள் எங்கள் கூட்டாளர்களுக்கு என்ன வழங்குகிறோம்',
      'offer1_t' => 'நிலையான திட்டங்களுக்கான அணுகல்',
      'offer1_d' => 'அனைத்து துறைகளிலும் நிறுவப்பட்ட வணிகங்களுடன் நாங்கள் பணியாற்றுகிறோம், செயல்படுத்துதல்-தலைமையிலான பணிகளின் நிலையான பைப்லைனை உருவாக்குகிறோம்.',
      'offer2_t' => 'கட்டமைக்கப்பட்ட வேலை சூழல்',
      'offer2_d' => 'தெளிவான நோக்கங்கள், வரையறுக்கப்பட்ட செயல்முறைகள் மற்றும் செயல்படுத்தல் வழிகாட்டுதல்கள், திட்டத்தில் என்ன எதிர்பார்க்கப்படுகிறது என்பதை நீங்கள் எப்போதும் அறிவீர்கள்.',
      'offer3_t' => 'பயிற்சி & தரையில் ஆதரவு',
      'offer3_d' => 'திட்டத்தைச் செயல்படுத்துவதற்கு முன்னும் பின்னும் தேவையான பயிற்சி, கருவிகள் மற்றும் வழிகாட்டுதலை நாங்கள் உங்களுக்கு வழங்குகிறோம்.',
      'offer4_t' => 'உள்ளடக்கிய வாய்ப்பு தளம்',
      'offer4_d' => 'பாலினம், பின்னணி அல்லது முந்தைய விற்பனை அனுபவம் ஆகியவற்றின் அடிப்படையில் எந்த கட்டுப்பாடுகளும் இல்லை.',
      'offer5_t' => 'செயல்திறன்-இணைக்கப்பட்ட வருவாய்',
      'offer5_d' => 'உங்கள் வருமானம் செயல்பாட்டுடனும் விளைவுகளுடனும் இணைக்கப்பட்டுள்ளது, பலனளிக்கும் நிலைத்தன்மை மற்றும் அர்ப்பணிப்பு.',
      'offer6_t' => 'நம்பகமான மாதாந்திர கொடுப்பனவுகள்',
      'offer6_d' => 'அனைத்து கொடுப்பனவுகளும் ஒரு வெளிப்படையான மாதாந்திர சுழற்சியைப் பின்பற்றுகின்றன, இது நிதிகளை நம்பிக்கையுடன் திட்டமிடவும் நிர்வகிக்கவும் உதவுகிறது.',
      'trust_title' => 'எங்களுடன் பணிபுரிவதை மக்கள் ஏன் நம்புகிறார்கள்',
      'trust1_d' => 'திட்டங்களில் ஈடுபட்டுள்ள நபர்கள்',
      'trust2_n' => 'நிரூபிக்கப்பட்டுள்ளது',
      'trust2_d' => 'பெரிய, விநியோகிக்கப்பட்ட களக் குழுக்களை நிர்வகித்த அனுபவம்',
      'trust3_n' => 'தெளிவு',
      'trust3_d' => 'தொடர்பு மற்றும் கட்டமைக்கப்பட்ட செயல்படுத்தல் மாதிரிகள்',
      'trust4_n' => 'நீண்ட கால',
      'trust4_d' => 'ஒத்துழைப்பு மனப்பான்மை, ஒரு முறை பணிகள் அல்ல',
      'voices_title' => 'களத்தில் இருந்து குரல்கள்',
      'apply_title' => 'திட்டப்பணிகளுக்கு விண்ணப்பிக்கவும்',
      'apply_subtitle' => 'எங்கள் நெட்வொர்க்கில் சேர கீழே உள்ள விவரங்களை நிரப்பவும்.',
      'form_partner_type' => 'நான் ஒரு...',
      'form_select' => 'விருப்பத்தைத் தேர்ந்தெடுக்கவும்',
      'form_individual' => 'தனிப்பட்ட தொழில்முறை',
      'form_agency' => 'ஏஜென்சி / டீம் லீட்',
      'form_message_opt' => 'செய்தி (விரும்பினால்)',
      'form_apply' => 'இப்போது விண்ணப்பிக்கவும்',
      'success_title' => 'விண்ணப்பம் பெறப்பட்டது!',
      'success_desc' => 'எங்கள் வளர்ச்சிக் கூட்டாளர்கள் பட்டியலில் உங்கள் விவரங்களைப் பெற்றுள்ளோம்.',
    ),
    'why-work-with-us' => 
    array (
      'hero_h1_a' => 'மரணதண்டனை அது',
      'hero_h1_b' => 'வணிகங்கள் நம்பலாம்.',
      'hero_desc' => 'கட்டமைக்கப்பட்ட குழுக்கள், ஒழுக்கமான செயல்முறைகள் மற்றும் நிலையான விளைவுகளை வழங்கும் நிலத்தில் செயல்படுத்துதல் ஆகியவற்றைக் கொண்ட வணிகங்களை நாங்கள் ஆதரிக்கிறோம்.',
      'hero_btn' => 'எங்கள் குழுவுடன் பேசுங்கள்',
      'scale_title' => 'செயல்படுத்துவதன் மூலம் அளவிடுதல் வரையறுக்கப்பட்டுள்ளது.',
      'scale_p1' => 'ஒரு வணிகத்தை அளவிடுவது என்பது யோசனைகளால் அரிதாகவே வரையறுக்கப்படுகிறது - இது செயல்படுத்துவதன் மூலம் வரையறுக்கப்படுகிறது. பிராந்தியங்கள், தயாரிப்புகள் மற்றும் வாடிக்கையாளர் பிரிவுகளில் வணிகங்கள் விரிவடைவதால், விற்பனை, மக்கள் மற்றும் நிலத்தடி செயல்பாடுகளை நிர்வகிப்பது மிகவும் சிக்கலானதாகிறது.',
      'scale_p2' => 'பிசானி பிரதர்ஸில், நாங்கள் செயல்படுத்தும் உரிமையைப் பெற நிறுவனங்களுடன் கூட்டு சேர்ந்துள்ளோம் - நாங்கள் அங்கு செல்வதற்குத் தேவையான குழுக்கள், செயல்முறைகள் மற்றும் விநியோகத்தை நிர்வகிக்கும் போது வளர்ச்சியில் கவனம் செலுத்துவதற்கு அவர்களுக்கு உதவுகிறோம்.',
      'challenges_title' => 'வணிகங்கள் எதிர்கொள்ளும் பொதுவான சவால்கள்',
      'challenges_sub' => 'இந்த இடைவெளிகள் வேகத்தை மெதுவாக்குகிறது மற்றும் வளர்ச்சியைத் தக்கவைக்க கடினமாக்குகிறது.',
      'ch1_t' => 'குழு மேலாண்மை',
      'ch1_d' => 'நம்பகமான ஆன்-கிரவுண்ட் குழுக்களை உருவாக்கி நிர்வகிப்பதில் சிரமம்.',
      'ch2_t' => 'சீரற்ற செயல்படுத்தல்',
      'ch2_d' => 'வெவ்வேறு நகரங்கள் அல்லது பிராந்தியங்களில் சீரற்ற செயல்படுத்தல்.',
      'ch3_t' => 'வரையறுக்கப்பட்ட பார்வை',
      'ch3_d' => 'விற்பனை செயல்திறன் மற்றும் கள செயல்பாடுகளில் வரையறுக்கப்பட்ட தெரிவுநிலை.',
      'ch4_t' => 'செயல்பாட்டு தாமதங்கள்',
      'ch4_d' => 'வணிகர் சேர்க்கை, வாடிக்கையாளர் கையகப்படுத்தல் அல்லது சேகரிப்புகளில் தாமதங்கள்.',
      'ch5_t' => 'தாக்கத்தை அளவிடுதல்',
      'ch5_d' => 'அளவிடக்கூடிய தாக்கத்துடன் பெரிய அளவிலான பிரச்சாரங்களை இயக்குவதில் உள்ள சவால்கள்.',
      'support_title' => 'உங்கள் வணிகத்தை நாங்கள் எப்படி ஆதரிக்கிறோம்',
      'support_sub' => 'சுயாதீனமாக அல்லது ஒன்றாக வேலை செய்ய வடிவமைக்கப்பட்ட ஒருங்கிணைந்த செயல்படுத்தல் ஆதரவு.',
      'svc1_t' => 'விற்பனை மற்றும் வளர்ச்சி தீர்வுகள்',
      'svc1_d' => 'FinTech, BFSI மற்றும் கடன் வழங்குதல் ஆகியவற்றில் வணிகர் ஆன்போர்டிங், முன்னணி உருவாக்கம் மற்றும் மாற்றங்களை ஆதரிக்கும் கட்டமைக்கப்பட்ட விற்பனை செயல்படுத்தல்.',
      'svc_link' => 'தீர்வை ஆராயுங்கள்',
      'svc2_t' => 'கணக்கெடுப்பு & சந்தை ஆராய்ச்சி',
      'svc2_d' => 'வாடிக்கையாளர்களைப் புரிந்துகொள்ளவும், வாய்ப்புகளைச் சரிபார்க்கவும் மற்றும் முடிவுகளை எடுக்கவும் வணிகங்களுக்கு உதவும் நிலத்தடி தரவு சேகரிப்பு மற்றும் சந்தை நுண்ணறிவு.',
      'svc3_t' => 'பணியாளர் தீர்வுகள்',
      'svc3_d' => 'விற்பனை, செயல்பாடுகள் மற்றும் வணிக விரிவாக்கத்தை ஆதரிப்பதற்காக தொழில்கள் முழுவதும் பயிற்சி பெற்ற, அளவிடக்கூடிய மனிதவளத்தைப் பயன்படுத்துதல்.',
      'svc4_t' => 'BTL & ATL செயல்படுத்தல்',
      'svc4_d' => 'பிராண்ட் செயல்படுத்தல்கள், தயாரிப்பு வெளியீடுகள் மற்றும் விளம்பரப் பிரச்சாரங்கள் ஆகியவற்றின் முடிவில் இருந்து இறுதி வரை செயல்படுத்துதல்.',
      'svc5_t' => 'கடன் & வசூல்',
      'svc5_d' => 'விற்பனை மற்றும் இணக்கமான வசூல், செயல்திறன் மற்றும் நம்பிக்கையை உறுதி செய்வதற்கான அர்ப்பணிப்பு குழுக்கள் மற்றும் கால் சென்டர் ஆதரவு.',
      'work_title' => 'வாடிக்கையாளர்களுடன் நாங்கள் எவ்வாறு வேலை செய்கிறோம்',
      'step1_t' => 'சீரமைக்கவும்',
      'step1_d' => 'உங்கள் வணிக இலக்குகள், சந்தை சூழல் மற்றும் செயல்படுத்தல் தேவைகள் ஆகியவற்றை நாங்கள் புரிந்துகொள்கிறோம்.',
      'step2_t' => 'வரிசைப்படுத்து',
      'step2_d' => 'பயிற்சி பெற்ற குழுக்கள், கருவிகள் மற்றும் பணிப்பாய்வுகளை உங்கள் நோக்கங்களுக்கு ஏற்ப அமைத்துள்ளோம்.',
      'step3_t' => 'செயல்படுத்து',
      'step3_d' => 'எங்கள் குழுக்கள் உங்கள் பிராண்டை தரையிலும் வாடிக்கையாளர் தொடுப்புள்ளிகளிலும் பிரதிநிதித்துவப்படுத்துகின்றன.',
      'step4_t' => 'உகந்ததாக்கு',
      'step4_d' => 'நாங்கள் செயல்திறனைக் கண்காணிக்கிறோம், செயல்முறைகளைச் செம்மைப்படுத்துகிறோம் மற்றும் விளைவுகளைத் தொடர்ந்து மேம்படுத்துகிறோம்.',
      'connect_title' => 'இணைப்போம்',
      'connect_sub' => 'விற்பனை வளர்ச்சி, சந்தை நுழைவு அல்லது இணக்கம்-தலைமையிலான செயல்பாடுகளை ஆதரிக்க நம்பகமான நிலத்தில் செயல்படுத்துவதை நீங்கள் தேடுகிறீர்கள் என்றால், உங்கள் தேவைகளைப் புரிந்துகொள்வதில் நாங்கள் மகிழ்ச்சியடைவோம்.',
      'form_talk' => 'எங்களுடன் பேசுங்கள்',
      'form_email' => 'மின்னஞ்சல் முகவரி',
      'form_phone_label' => 'தொடர்பு எண்',
      'form_industry' => 'தொழில்',
      'form_industry_ph' => 'தொழில்துறையைத் தேர்ந்தெடுக்கவும்',
      'form_services' => 'நீங்கள் ஆர்வமுள்ள சேவைகள்',
      'form_brief' => 'சுருக்கமான தேவை (விரும்பினால்)',
      'form_brief_ph' => 'நீங்கள் எதை அடைய விரும்புகிறீர்கள் என்பதை சுருக்கமாக எங்களிடம் கூறுங்கள்.',
      'form_submit_req' => 'தேவையை சமர்ப்பிக்கவும்',
    ),
    'growth-partner' => 
    array (
      'hero_eyebrow' => 'கூட்டாளர் திட்டம்',
      'hero_h1_a' => 'பிசானி சகோதரர்களுடன் வளருங்கள்.',
      'hero_h1_b' => 'உங்கள் விதிமுறைகளில் வேலை செய்யுங்கள்.',
      'hero_btn' => 'பங்குதாரராக மாற விண்ணப்பிக்கவும்',
