      'c3_title' => 'అసమర్థ ప్రక్రియలు',
      'c3_desc' => 'అసమర్థమైన విక్రయ ప్రక్రియలు మరియు నిర్మాణాత్మక ఫాలో-అప్ మెకానిజమ్స్ లేకపోవడం మార్పిడి రేట్లను తగ్గించడం.',
