    'partner-with-us' => 
    array (
      'hero_title' => 'మాతో భాగస్వామి',
      'hero_desc' => 'నిజమైన ప్రాజెక్ట్‌లతో ఎదగడానికి సిద్ధంగా ఉన్న వ్యక్తులు మరియు బృందాల కోసం రూపొందించబడిన అవకాశాలు.',
      'hero_btn' => 'ప్రాజెక్ట్‌లపై పని చేయడానికి దరఖాస్తు చేయండి',
      'intro_p1' => 'బిసాని బ్రదర్స్ వద్ద, భారతదేశం అంతటా పెద్ద ఎత్తున వ్యాపార అమలు ప్రాజెక్టులలో పాల్గొనేందుకు వ్యక్తులు, ఏజెన్సీలు మరియు బృందాల కోసం మేము నిర్మాణాత్మక పని అవకాశాలను సృష్టిస్తాము.',
      'intro_p2' => 'మీరు స్వతంత్ర ప్రొఫెషనల్ లేదా ఆన్-గ్రౌండ్ వర్క్‌ఫోర్స్‌తో ఉన్న సంస్థ అయినా, మేము స్థిరమైన ప్రాజెక్ట్‌లు, స్పష్టమైన ప్రక్రియలు మరియు నమ్మకమైన నిశ్చితార్థానికి యాక్సెస్‌ను అందిస్తాము — వ్యాపారాలను విస్తరిస్తున్న వాటితో పాటుగా మీరు సంపాదించడానికి, నేర్చుకునేందుకు మరియు అభివృద్ధి చెందడానికి వీలు కల్పిస్తాము.',
      'intro_p3' => 'మాతో ఇప్పటికే అనుబంధించబడిన 2,100+ మంది వ్యక్తులతో, మా నెట్‌వర్క్ నమ్మకం, అమలు మరియు దీర్ఘకాలిక సహకారంపై నిర్మించబడింది.',
      'opp_title' => 'మీరు పని చేయగల అవకాశాలు',
      'opp_subtitle' => 'మేము అనేక రకాల ఆన్-గ్రౌండ్ మరియు ఫీల్డ్ ఎగ్జిక్యూషన్ ప్రాజెక్ట్‌లలో భాగస్వాములను కలిగి ఉంటాము, వీటితో సహా:',
      'opp1' => 'విక్రయాలు మరియు వ్యాపారి ఆన్‌బోర్డింగ్ కార్యక్రమాలు',
      'opp2' => 'మార్కెట్ సర్వేలు, ఆడిట్‌లు మరియు కస్టమర్ వెరిఫికేషన్',
      'opp3' => 'ఫీల్డ్ యాక్టివేషన్ మరియు బ్రాండ్ అవుట్‌రీచ్ ప్రోగ్రామ్‌లు',
      'opp4' => 'రుణ మద్దతు, డాక్యుమెంటేషన్ మరియు సేకరణల సహాయం',
      'opp5' => 'భూభాగ విస్తరణ మరియు పైలట్ మార్కెట్ ప్రాజెక్టులు',
      'opp_closing' => 'ప్రాంతం, స్కేల్ మరియు వ్యవధిని బట్టి అవకాశాలు మారుతూ ఉంటాయి - వ్యక్తులు మరియు ఏజెన్సీలు తమ సామర్థ్యానికి అనుగుణంగా పనిని కనుగొనడానికి వీలు కల్పిస్తుంది.',
      'offer_title' => 'మేము మా భాగస్వాములకు ఏమి అందిస్తున్నాము',
      'offer1_t' => 'స్థిరమైన ప్రాజెక్ట్‌లకు యాక్సెస్',
