      'offer2_t' => 'నిర్మాణాత్మక పని వాతావరణం',
      'offer2_d' => 'క్లియర్ స్కోప్‌లు, డిఫైన్డ్ ప్రాసెస్‌లు మరియు ఎగ్జిక్యూషన్ గైడ్‌లైన్‌లు ప్రాజెక్ట్‌లో ఏమి ఆశించబడతాయో మీకు ఎల్లప్పుడూ తెలుసని నిర్ధారిస్తుంది.',
      'offer3_t' => 'శిక్షణ & ఆన్-గ్రౌండ్ సపోర్ట్',
      'offer3_d' => 'ప్రాజెక్ట్ అమలుకు ముందు మరియు సమయంలో అవసరమైన శిక్షణ, సాధనాలు మరియు మార్గదర్శకాలను మేము మీకు అందిస్తాము.',
      'offer4_t' => 'కలుపుకొని అవకాశాల వేదిక',
      'offer4_d' => 'లింగం, నేపథ్యం లేదా ముందస్తు విక్రయాల అనుభవం ఆధారంగా ఎలాంటి పరిమితులు లేవు.',
      'offer5_t' => 'పనితీరు-లింక్డ్ ఆదాయాలు',
      'offer5_d' => 'మీ ఆదాయాలు అమలు మరియు ఫలితాలు, రివార్డింగ్ స్థిరత్వం మరియు నిబద్ధతతో ముడిపడి ఉన్నాయి.',
      'offer6_t' => 'విశ్వసనీయ నెలవారీ చెల్లింపులు',
      'offer6_d' => 'అన్ని చెల్లింపులు పారదర్శకంగా నెలవారీ చక్రాన్ని అనుసరిస్తాయి, మీరు ఆర్థిక వ్యవహారాలను నమ్మకంగా ప్లాన్ చేయడంలో మరియు నిర్వహించడంలో సహాయపడతాయి.',
      'trust_title' => 'ప్రజలు మాతో పనిచేయడాన్ని ఎందుకు విశ్వసిస్తారు',
      'trust1_d' => 'ప్రాజెక్ట్‌లలో నిమగ్నమై ఉన్న వ్యక్తులు',
      'trust2_n' => 'నిరూపించబడింది',
