    'why-work-with-us' => 
    array (
      'hero_h1_a' => 'అమలు ఆ',
      'hero_h1_b' => 'వ్యాపారాలు ఆధారపడవచ్చు.',
      'hero_desc' => 'మేము నిర్మాణాత్మక బృందాలు, క్రమశిక్షణతో కూడిన ప్రక్రియలు మరియు స్థిరమైన ఫలితాలను అందించే ఆన్-గ్రౌండ్ ఎగ్జిక్యూషన్‌తో వ్యాపారాలకు మద్దతు ఇస్తున్నాము.',
      'hero_btn' => 'మా బృందంతో మాట్లాడండి',
      'scale_title' => 'స్కేలింగ్ అమలు ద్వారా పరిమితం చేయబడింది.',
      'scale_p1' => 'వ్యాపారాన్ని స్కేలింగ్ చేయడం చాలా అరుదుగా ఆలోచనల ద్వారా పరిమితం చేయబడుతుంది - ఇది అమలు ద్వారా పరిమితం చేయబడింది. ప్రాంతాలు, ఉత్పత్తులు మరియు కస్టమర్ విభాగాల్లో వ్యాపారాలు విస్తరిస్తున్నందున, విక్రయాలు, వ్యక్తులు మరియు ఆన్-గ్రౌండ్ కార్యకలాపాలను నిర్వహించడం చాలా క్లిష్టంగా మారుతుంది.',
      'scale_p2' => 'Bisani Brothers వద్ద, మేము ఎగ్జిక్యూషన్ యాజమాన్యాన్ని తీసుకోవడానికి సంస్థలతో భాగస్వామ్యం చేస్తాము — మేము అక్కడికి చేరుకోవడానికి అవసరమైన బృందాలు, ప్రక్రియలు మరియు డెలివరీని నిర్వహించేటప్పుడు వృద్ధిపై దృష్టి పెట్టడంలో వారికి సహాయపడతాము.',
      'challenges_title' => 'వ్యాపారాలు ఎదుర్కొంటున్న సాధారణ సవాళ్లు',
      'challenges_sub' => 'ఈ ఖాళీలు వేగాన్ని నెమ్మదిస్తాయి మరియు వృద్ధిని కొనసాగించడం కష్టతరం చేస్తాయి.',
      'ch1_t' => 'జట్టు నిర్వహణ',
      'ch1_d' => 'విశ్వసనీయమైన ఆన్-గ్రౌండ్ బృందాలను నిర్మించడం మరియు నిర్వహించడం కష్టం.',
      'ch2_t' => 'అస్థిరమైన అమలు',
      'ch2_d' => 'వివిధ నగరాలు లేదా ప్రాంతాలలో అస్థిరమైన అమలు.',
      'ch3_t' => 'పరిమిత దృశ్యమానత',
      'ch3_d' => 'విక్రయాల పనితీరు మరియు ఫీల్డ్ కార్యకలాపాలలో పరిమిత దృశ్యమానత.',
      'ch4_t' => 'కార్యాచరణ ఆలస్యం',
