      'ch5_t' => 'ప్రభావాన్ని కొలవడం',
      'ch5_d' => 'కొలవగల ప్రభావంతో పెద్ద ఎత్తున ప్రచారాలను నిర్వహించడంలో సవాళ్లు.',
      'support_title' => 'మేము మీ వ్యాపారానికి ఎలా మద్దతిస్తాము',
      'support_sub' => 'స్వతంత్రంగా లేదా కలిసి పనిచేయడానికి రూపొందించబడిన ఇంటిగ్రేటెడ్ ఎగ్జిక్యూషన్ సపోర్ట్.',
      'svc1_t' => 'సేల్స్ & గ్రోత్ సొల్యూషన్స్',
      'svc1_d' => 'ఫిన్‌టెక్, BFSI మరియు లెండింగ్ అంతటా వ్యాపారి ఆన్‌బోర్డింగ్, లీడ్ జనరేషన్ మరియు మార్పిడులకు మద్దతునిచ్చే నిర్మాణాత్మక విక్రయాల అమలు.',
      'svc_link' => 'పరిష్కారాన్ని అన్వేషించండి',
