      'c1_title' => 'ಸ್ವಾಧೀನದ ತೊಂದರೆ',
      'c1_desc' => 'ಪ್ರದೇಶಗಳಾದ್ಯಂತ ವ್ಯಾಪಾರಿಗಳನ್ನು ಸಮರ್ಥವಾಗಿ ಸ್ವಾಧೀನಪಡಿಸಿಕೊಳ್ಳುವ ಮತ್ತು ಆನ್‌ಬೋರ್ಡಿಂಗ್ ಮಾಡುವಲ್ಲಿ ತೊಂದರೆ.',
      'c2_title' => 'ಕಡಿಮೆ ಗೋಚರತೆ',
      'c2_desc' => 'ಗ್ರಾಹಕರ ತೊಡಗಿಸಿಕೊಳ್ಳುವಿಕೆ ಮತ್ತು ಮಾರುಕಟ್ಟೆ ಒಳನೋಟಗಳಲ್ಲಿ ಕಡಿಮೆ ಗೋಚರತೆ, ತಪ್ಪಿದ ಅವಕಾಶಗಳಿಗೆ ಕಾರಣವಾಗುತ್ತದೆ.',
      'c3_title' => 'ಅಸಮರ್ಥ ಪ್ರಕ್ರಿಯೆಗಳು',
      'c3_desc' => 'ಅಸಮರ್ಥ ಮಾರಾಟ ಪ್ರಕ್ರಿಯೆಗಳು ಮತ್ತು ಪರಿವರ್ತನೆ ದರಗಳನ್ನು ಕಡಿಮೆ ಮಾಡುವ ರಚನಾತ್ಮಕ ಅನುಸರಣಾ ಕಾರ್ಯವಿಧಾನಗಳ ಕೊರತೆ.',
      'c4_title' => 'ವಿಸ್ತರಣೆ ಅಡಚಣೆಗಳು',
      'c4_desc' => 'ಸ್ಥಿರವಾದ ಕಾರ್ಯಕ್ಷಮತೆಯ ಮಾನದಂಡಗಳನ್ನು ನಿರ್ವಹಿಸುವಾಗ ಪ್ರದೇಶಗಳನ್ನು ವಿಸ್ತರಿಸುವಲ್ಲಿ ಸವಾಲುಗಳು.',
      'd1' => 'ವ್ಯಾಪಾರಿ ಆನ್‌ಬೋರ್ಡಿಂಗ್ ಮತ್ತು ಸಕ್ರಿಯಗೊಳಿಸುವಿಕೆ',
      'd2' => 'ಪ್ರಮುಖ ಉತ್ಪಾದನೆ ಮತ್ತು ರಚನಾತ್ಮಕ ಮಾರಾಟದ ಫನಲ್‌ಗಳು',
      'd3' => 'ಮಾರಾಟ ಪರಿವರ್ತನೆ ಮತ್ತು ಅನುಸರಣಾ ನಿರ್ವಹಣೆ',
      'd4' => 'ಮಾರುಕಟ್ಟೆ ಸಮೀಕ್ಷೆಗಳು ಮತ್ತು ಕ್ರಿಯಾಶೀಲ ಗ್ರಾಹಕರ ಒಳನೋಟಗಳು',
      'd5' => 'ಪ್ರದೇಶದ ವಿಸ್ತರಣೆ ಮತ್ತು ಕಾರ್ಯಕ್ಷಮತೆ ಟ್ರ್ಯಾಕಿಂಗ್',
    ),
    'survey-market-research' => 
