      'intro_highlight' => 'ಸಮೀಕ್ಷೆ ಮತ್ತು ಮಾರುಕಟ್ಟೆ ಸಂಶೋಧನೆ',
      'c1_title' => 'ಸೀಮಿತ ಗೋಚರತೆ',
      'c1_desc' => 'ಗುರಿ ಮಾರುಕಟ್ಟೆಗಳಲ್ಲಿ ಗ್ರಾಹಕರ ಆದ್ಯತೆಗಳು ಮತ್ತು ಸ್ಪರ್ಧಿಗಳ ಚಟುವಟಿಕೆಗಳಿಗೆ ಸೀಮಿತ ಗೋಚರತೆ.',
      'c2_title' => 'ಡೇಟಾ ಅಂತರಗಳು',
