      'c3_title' => 'ಮೌಲ್ಯೀಕರಣದ ಸಮಸ್ಯೆಗಳು',
      'c3_desc' => 'ಪ್ರಮುಖ ಹೂಡಿಕೆಗಳು ಅಥವಾ ರೋಲ್‌ಔಟ್‌ಗಳ ಮೊದಲು ಊಹೆಗಳನ್ನು ಮೌಲ್ಯೀಕರಿಸುವಲ್ಲಿ ತೊಂದರೆ.',
      'c4_title' => 'ಅಸಮಂಜಸ ಡೇಟಾ',
      'c4_desc' => 'ನಿರ್ಧಾರದ ಗುಣಮಟ್ಟ ಮತ್ತು ವೇಗದ ಮೇಲೆ ಪರಿಣಾಮ ಬೀರುವ ಅಸಂಗತ ಡೇಟಾ ಸಂಗ್ರಹಣೆ.',
      'deliver_desc' => 'ನಿಖರವಾದ, ರಚನಾತ್ಮಕ ಡೇಟಾವನ್ನು ಸಂಗ್ರಹಿಸಲು ನಾವು ತರಬೇತಿ ಪಡೆದ ಕ್ಷೇತ್ರ ತಂಡಗಳನ್ನು ನಿಯೋಜಿಸುತ್ತೇವೆ, ನಿಮ್ಮ ಮಾರುಕಟ್ಟೆಯ ಭೂದೃಶ್ಯದ ಸಂಪೂರ್ಣ ಚಿತ್ರವನ್ನು ನೀವು ಪಡೆಯುತ್ತೀರಿ ಎಂದು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳುತ್ತೇವೆ.',
      'd1' => 'ಗ್ರಾಹಕ ಮತ್ತು ವ್ಯಾಪಾರಿ ಸಮೀಕ್ಷೆಗಳು',
      'd2' => 'ಮಾರುಕಟ್ಟೆ ಮತ್ತು ಪ್ರದೇಶದ ಮೌಲ್ಯಮಾಪನಗಳು',
      'd3' => 'ಉತ್ಪನ್ನ ಪ್ರತಿಕ್ರಿಯೆ ಮತ್ತು ಮಾದರಿ ಅಧ್ಯಯನಗಳು',
      'd4' => 'ರಚನಾತ್ಮಕ ವರದಿಯೊಂದಿಗೆ ಡೇಟಾ ಸಂಗ್ರಹಣೆ',
      'form_build_title' => 'ಡೇಟಾವನ್ನು ನಿರ್ಧಾರಗಳಾಗಿ ಪರಿವರ್ತಿಸಿ',
