      'c4_title' => 'ಗುಣಮಟ್ಟ ನಿಯಂತ್ರಣ',
      'c4_desc' => 'ವಿತರಿಸಿದ ತಂಡಗಳಾದ್ಯಂತ ಅಸಮಂಜಸ ಗುಣಮಟ್ಟ ಮತ್ತು ತರಬೇತಿ ಮಾನದಂಡಗಳು.',
      'deliver_desc' => 'ನಾವು ಸಮಗ್ರ ಸಿಬ್ಬಂದಿ ಪರಿಹಾರಗಳನ್ನು ಒದಗಿಸುತ್ತೇವೆ ಅದು ನಿಮ್ಮ ಕಾರ್ಯಾಚರಣೆಗಳನ್ನು ಎಂದಿಗೂ ಕಳೆದುಕೊಳ್ಳುವುದಿಲ್ಲ ಎಂದು ಖಚಿತಪಡಿಸುತ್ತದೆ.',
      'd1' => 'ಕೈಗಾರಿಕೆಗಳಾದ್ಯಂತ ತರಬೇತಿ ಪಡೆದ ಮಾನವಶಕ್ತಿ ನಿಯೋಜನೆ',
      'd2' => 'ಮಾರಾಟ, ಕಾರ್ಯಾಚರಣೆಗಳು ಮತ್ತು ಬೆಂಬಲ ಸಿಬ್ಬಂದಿ',
      'd3' => 'ಹೊಂದಿಕೊಳ್ಳುವ ಸಿಬ್ಬಂದಿ ಮಾದರಿಗಳು (ಅಲ್ಪಾವಧಿ ಮತ್ತು ದೀರ್ಘಾವಧಿ)',
