      'hero_desc' => 'ರಚನಾತ್ಮಕ ಸಾಲ ಮಾರಾಟ ಮತ್ತು ಸಂಗ್ರಹಣೆಗಳ ಕಾರ್ಯಗತಗೊಳಿಸುವಿಕೆ.',
