      'view_category_articles' => 'ಎಲ್ಲಾ {category} ಲೇಖನಗಳನ್ನು ವೀಕ್ಷಿಸಿ',
      'browse_tagged' => '{tag} ಟ್ಯಾಗ್ ಮಾಡಲಾದ ಲೇಖನಗಳನ್ನು ಬ್ರೌಸ್ ಮಾಡಿ',
    ),
    'partner-with-us' => 
    array (
      'hero_title' => 'ನಮ್ಮೊಂದಿಗೆ ಪಾಲುದಾರ',
      'hero_desc' => 'ನೈಜ ಯೋಜನೆಗಳೊಂದಿಗೆ ಬೆಳೆಯಲು ಸಿದ್ಧವಾಗಿರುವ ವ್ಯಕ್ತಿಗಳು ಮತ್ತು ತಂಡಗಳಿಗಾಗಿ ನಿರ್ಮಿಸಲಾದ ಅವಕಾಶಗಳು.',
      'hero_btn' => 'ಯೋಜನೆಗಳಲ್ಲಿ ಕೆಲಸ ಮಾಡಲು ಅನ್ವಯಿಸಿ',
      'intro_p1' => 'ಬಿಸಾನಿ ಬ್ರದರ್ಸ್‌ನಲ್ಲಿ, ನಾವು ವ್ಯಕ್ತಿಗಳು, ಏಜೆನ್ಸಿಗಳು ಮತ್ತು ತಂಡಗಳಿಗೆ ಭಾರತದಾದ್ಯಂತ ದೊಡ್ಡ ಪ್ರಮಾಣದ ವ್ಯಾಪಾರ ಕಾರ್ಯಗತಗೊಳಿಸುವ ಯೋಜನೆಗಳಲ್ಲಿ ಭಾಗವಹಿಸಲು ರಚನಾತ್ಮಕ ಕೆಲಸದ ಅವಕಾಶಗಳನ್ನು ರಚಿಸುತ್ತೇವೆ.',
      'intro_p2' => 'ನೀವು ಸ್ವತಂತ್ರ ವೃತ್ತಿಪರರಾಗಿರಲಿ ಅಥವಾ ಆನ್-ಗ್ರೌಂಡ್ ವರ್ಕ್‌ಫೋರ್ಸ್ ಹೊಂದಿರುವ ಸಂಸ್ಥೆಯಾಗಿರಲಿ, ನಾವು ಸ್ಥಿರವಾದ ಯೋಜನೆಗಳು, ಸ್ಪಷ್ಟ ಪ್ರಕ್ರಿಯೆಗಳು ಮತ್ತು ವಿಶ್ವಾಸಾರ್ಹ ತೊಡಗಿಸಿಕೊಳ್ಳುವಿಕೆಗೆ ಪ್ರವೇಶವನ್ನು ನೀಡುತ್ತೇವೆ - ವ್ಯಾಪಾರಗಳನ್ನು ವಿಸ್ತರಿಸುವುದರ ಜೊತೆಗೆ ಗಳಿಸಲು, ಕಲಿಯಲು ಮತ್ತು ಬೆಳೆಯಲು ನಿಮಗೆ ಅನುವು ಮಾಡಿಕೊಡುತ್ತದೆ.',
      'intro_p3' => '2,100+ ಜನರು ಈಗಾಗಲೇ ನಮ್ಮೊಂದಿಗೆ ಸಂಬಂಧ ಹೊಂದಿದ್ದು, ನಮ್ಮ ನೆಟ್‌ವರ್ಕ್ ನಂಬಿಕೆ, ಕಾರ್ಯಗತಗೊಳಿಸುವಿಕೆ ಮತ್ತು ದೀರ್ಘಾವಧಿಯ ಸಹಯೋಗದ ಮೇಲೆ ನಿರ್ಮಿಸಲಾಗಿದೆ.',
      'opp_title' => 'ನೀವು ಕೆಲಸ ಮಾಡಬಹುದಾದ ಅವಕಾಶಗಳು',
      'opp_subtitle' => 'ನಾವು ವ್ಯಾಪಕ ಶ್ರೇಣಿಯ ಆನ್-ಗ್ರೌಂಡ್ ಮತ್ತು ಫೀಲ್ಡ್ ಎಕ್ಸಿಕ್ಯೂಶನ್ ಪ್ರಾಜೆಕ್ಟ್‌ಗಳಲ್ಲಿ ಪಾಲುದಾರರನ್ನು ತೊಡಗಿಸಿಕೊಳ್ಳುತ್ತೇವೆ, ಅವುಗಳೆಂದರೆ:',
      'opp1' => 'ಮಾರಾಟ ಮತ್ತು ವ್ಯಾಪಾರಿ ಆನ್‌ಬೋರ್ಡಿಂಗ್ ಉಪಕ್ರಮಗಳು',
      'opp2' => 'ಮಾರುಕಟ್ಟೆ ಸಮೀಕ್ಷೆಗಳು, ಲೆಕ್ಕಪರಿಶೋಧನೆಗಳು ಮತ್ತು ಗ್ರಾಹಕರ ಪರಿಶೀಲನೆ',
      'opp3' => 'ಕ್ಷೇತ್ರ ಸಕ್ರಿಯಗೊಳಿಸುವಿಕೆ ಮತ್ತು ಬ್ರಾಂಡ್ ಔಟ್ರೀಚ್ ಕಾರ್ಯಕ್ರಮಗಳು',
      'opp4' => 'ಸಾಲ ನೀಡುವ ಬೆಂಬಲ, ದಾಖಲಾತಿ ಮತ್ತು ಸಂಗ್ರಹಣೆಗಳ ಸಹಾಯ',
      'opp5' => 'ಪ್ರದೇಶದ ವಿಸ್ತರಣೆ ಮತ್ತು ಪ್ರಾಯೋಗಿಕ ಮಾರುಕಟ್ಟೆ ಯೋಜನೆಗಳು',
      'opp_closing' => 'ಅವಕಾಶಗಳು ಪ್ರದೇಶ, ಪ್ರಮಾಣ ಮತ್ತು ಅವಧಿಯ ಮೂಲಕ ಬದಲಾಗುತ್ತವೆ - ವ್ಯಕ್ತಿಗಳು ಮತ್ತು ಏಜೆನ್ಸಿಗಳು ತಮ್ಮ ಸಾಮರ್ಥ್ಯಕ್ಕೆ ಅನುಗುಣವಾಗಿ ಕೆಲಸವನ್ನು ಹುಡುಕಲು ಅನುವು ಮಾಡಿಕೊಡುತ್ತದೆ.',
      'offer_title' => 'ನಾವು ನಮ್ಮ ಪಾಲುದಾರರಿಗೆ ಏನು ನೀಡುತ್ತೇವೆ',
      'offer1_t' => 'ಸ್ಥಿರ ಯೋಜನೆಗಳಿಗೆ ಪ್ರವೇಶ',
      'offer1_d' => 'ನಾವು ಕ್ಷೇತ್ರಗಳಾದ್ಯಂತ ಸ್ಥಾಪಿತ ವ್ಯವಹಾರಗಳೊಂದಿಗೆ ಕೆಲಸ ಮಾಡುತ್ತೇವೆ, ಕಾರ್ಯಗತಗೊಳಿಸುವಿಕೆ-ನೇತೃತ್ವದ ಕಾರ್ಯಯೋಜನೆಗಳ ಸ್ಥಿರ ಪೈಪ್‌ಲೈನ್ ಅನ್ನು ರಚಿಸುತ್ತೇವೆ.',
      'offer2_t' => 'ರಚನಾತ್ಮಕ ಕೆಲಸದ ಪರಿಸರ',
      'offer2_d' => 'ಸ್ಪಷ್ಟವಾದ ವ್ಯಾಪ್ತಿಗಳು, ವ್ಯಾಖ್ಯಾನಿಸಲಾದ ಪ್ರಕ್ರಿಯೆಗಳು ಮತ್ತು ಕಾರ್ಯಗತಗೊಳಿಸುವ ಮಾರ್ಗಸೂಚಿಗಳು ಯೋಜನೆಯಲ್ಲಿ ಏನನ್ನು ನಿರೀಕ್ಷಿಸಬಹುದು ಎಂಬುದನ್ನು ನೀವು ಯಾವಾಗಲೂ ತಿಳಿದಿರುತ್ತೀರಿ ಎಂದು ಖಚಿತಪಡಿಸುತ್ತದೆ.',
      'offer3_t' => 'ತರಬೇತಿ ಮತ್ತು ಆನ್-ಗ್ರೌಂಡ್ ಬೆಂಬಲ',
      'offer3_d' => 'ಪ್ರಾಜೆಕ್ಟ್ ಕಾರ್ಯಗತಗೊಳಿಸುವ ಮೊದಲು ಮತ್ತು ಸಮಯದಲ್ಲಿ ನಾವು ನಿಮಗೆ ಅಗತ್ಯವಾದ ತರಬೇತಿ, ಪರಿಕರಗಳು ಮತ್ತು ಮಾರ್ಗದರ್ಶನದೊಂದಿಗೆ ಸಜ್ಜುಗೊಳಿಸುತ್ತೇವೆ.',
      'offer4_t' => 'ಅಂತರ್ಗತ ಅವಕಾಶ ವೇದಿಕೆ',
      'offer4_d' => 'ಲಿಂಗ, ಹಿನ್ನೆಲೆ ಅಥವಾ ಮುಂಚಿನ ಮಾರಾಟದ ಅನುಭವದ ಆಧಾರದ ಮೇಲೆ ಯಾವುದೇ ನಿರ್ಬಂಧಗಳಿಲ್ಲ.',
      'offer5_t' => 'ಕಾರ್ಯಕ್ಷಮತೆ-ಸಂಯೋಜಿತ ಗಳಿಕೆಗಳು',
      'offer5_d' => 'ನಿಮ್ಮ ಗಳಿಕೆಗಳು ಕಾರ್ಯಗತಗೊಳಿಸುವಿಕೆ ಮತ್ತು ಫಲಿತಾಂಶಗಳು, ಪ್ರತಿಫಲದಾಯಕ ಸ್ಥಿರತೆ ಮತ್ತು ಬದ್ಧತೆಗೆ ಸಂಬಂಧಿಸಿವೆ.',
      'offer6_t' => 'ವಿಶ್ವಾಸಾರ್ಹ ಮಾಸಿಕ ಪಾವತಿಗಳು',
      'offer6_d' => 'ಎಲ್ಲಾ ಪಾವತಿಗಳು ಪಾರದರ್ಶಕ ಮಾಸಿಕ ಚಕ್ರವನ್ನು ಅನುಸರಿಸುತ್ತವೆ, ಇದು ನಿಮಗೆ ವಿಶ್ವಾಸದಿಂದ ಹಣಕಾಸುಗಳನ್ನು ಯೋಜಿಸಲು ಮತ್ತು ನಿರ್ವಹಿಸಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ.',
      'trust_title' => 'ಜನರು ನಮ್ಮೊಂದಿಗೆ ಕೆಲಸ ಮಾಡುವುದನ್ನು ಏಕೆ ನಂಬುತ್ತಾರೆ',
      'trust1_d' => 'ಯೋಜನೆಗಳಾದ್ಯಂತ ತೊಡಗಿರುವ ವ್ಯಕ್ತಿಗಳು',
      'trust2_n' => 'ಸಾಬೀತಾಗಿದೆ',
      'trust2_d' => 'ದೊಡ್ಡ, ವಿತರಿಸಿದ ಕ್ಷೇತ್ರ ತಂಡಗಳನ್ನು ನಿರ್ವಹಿಸುವ ಅನುಭವ',
      'trust3_n' => 'ತೆರವುಗೊಳಿಸಿ',
      'trust3_d' => 'ಸಂವಹನ ಮತ್ತು ರಚನಾತ್ಮಕ ಮರಣದಂಡನೆ ಮಾದರಿಗಳು',
      'trust4_n' => 'ದೀರ್ಘಾವಧಿ',
      'trust4_d' => 'ಸಹಯೋಗದ ಮನಸ್ಥಿತಿ, ಒಂದು-ಆಫ್ ಕಾರ್ಯಯೋಜನೆಯಲ್ಲ',
      'voices_title' => 'ಕ್ಷೇತ್ರದಿಂದ ಧ್ವನಿಗಳು',
      'apply_title' => 'ಯೋಜನೆಗಳಲ್ಲಿ ಕೆಲಸ ಮಾಡಲು ಅನ್ವಯಿಸಿ',
      'apply_subtitle' => 'ನಮ್ಮ ನೆಟ್‌ವರ್ಕ್‌ಗೆ ಸೇರಲು ನಿಮ್ಮ ವಿವರಗಳನ್ನು ಕೆಳಗೆ ಭರ್ತಿ ಮಾಡಿ.',
      'form_partner_type' => 'ನಾನು ಒಬ್ಬ...',
      'form_select' => 'ಆಯ್ಕೆಯನ್ನು ಆರಿಸಿ',
      'form_individual' => 'ವೈಯಕ್ತಿಕ ವೃತ್ತಿಪರ',
      'form_agency' => 'ಏಜೆನ್ಸಿ / ಟೀಮ್ ಲೀಡ್',
      'form_message_opt' => 'ಸಂದೇಶ (ಐಚ್ಛಿಕ)',
      'form_apply' => 'ಈಗ ಅನ್ವಯಿಸು',
      'success_title' => 'ಅರ್ಜಿ ಸ್ವೀಕರಿಸಲಾಗಿದೆ!',
      'success_desc' => 'ನಮ್ಮ ಬೆಳವಣಿಗೆ ಪಾಲುದಾರರ ಪಟ್ಟಿಯಲ್ಲಿ ನಿಮ್ಮ ವಿವರಗಳನ್ನು ನಾವು ಸ್ವೀಕರಿಸಿದ್ದೇವೆ.',
    ),
    'why-work-with-us' => 
    array (
      'hero_h1_a' => 'ಮರಣದಂಡನೆ ಅದು',
      'hero_h1_b' => 'ವ್ಯಾಪಾರಗಳು ಅವಲಂಬಿಸಬಹುದು.',
      'hero_desc' => 'ಸ್ಥಿರವಾದ ಫಲಿತಾಂಶಗಳನ್ನು ನೀಡುವ ರಚನಾತ್ಮಕ ತಂಡಗಳು, ಶಿಸ್ತುಬದ್ಧ ಪ್ರಕ್ರಿಯೆಗಳು ಮತ್ತು ಆನ್-ಗ್ರೌಂಡ್ ಎಕ್ಸಿಕ್ಯೂಶನ್‌ನೊಂದಿಗೆ ನಾವು ವ್ಯವಹಾರಗಳನ್ನು ಬೆಂಬಲಿಸುತ್ತೇವೆ.',
      'hero_btn' => 'ನಮ್ಮ ತಂಡದೊಂದಿಗೆ ಮಾತನಾಡಿ',
      'scale_title' => 'ಸ್ಕೇಲಿಂಗ್ ಅನ್ನು ಎಕ್ಸಿಕ್ಯೂಶನ್ ಮೂಲಕ ಸೀಮಿತಗೊಳಿಸಲಾಗಿದೆ.',
      'scale_p1' => 'ವ್ಯವಹಾರವನ್ನು ಸ್ಕೇಲಿಂಗ್ ಮಾಡುವುದು ಕಲ್ಪನೆಗಳಿಂದ ವಿರಳವಾಗಿ ಸೀಮಿತವಾಗಿದೆ - ಇದು ಕಾರ್ಯಗತಗೊಳಿಸುವಿಕೆಯಿಂದ ಸೀಮಿತವಾಗಿದೆ. ಪ್ರದೇಶಗಳು, ಉತ್ಪನ್ನಗಳು ಮತ್ತು ಗ್ರಾಹಕರ ವಿಭಾಗಗಳಾದ್ಯಂತ ವ್ಯಾಪಾರಗಳು ವಿಸ್ತರಿಸುತ್ತಿದ್ದಂತೆ, ಮಾರಾಟ, ಜನರು ಮತ್ತು ನೆಲದ ಕಾರ್ಯಾಚರಣೆಗಳನ್ನು ನಿರ್ವಹಿಸುವುದು ಹೆಚ್ಚು ಸಂಕೀರ್ಣವಾಗುತ್ತದೆ.',
      'scale_p2' => 'ಬಿಸಾನಿ ಬ್ರದರ್ಸ್‌ನಲ್ಲಿ, ಮರಣದಂಡನೆಯ ಮಾಲೀಕತ್ವವನ್ನು ತೆಗೆದುಕೊಳ್ಳಲು ನಾವು ಸಂಸ್ಥೆಗಳೊಂದಿಗೆ ಪಾಲುದಾರರಾಗಿದ್ದೇವೆ - ನಾವು ಅಲ್ಲಿಗೆ ಹೋಗಲು ಅಗತ್ಯವಿರುವ ತಂಡಗಳು, ಪ್ರಕ್ರಿಯೆಗಳು ಮತ್ತು ವಿತರಣೆಯನ್ನು ನಿರ್ವಹಿಸುವಾಗ ಬೆಳವಣಿಗೆಯ ಮೇಲೆ ಕೇಂದ್ರೀಕರಿಸಲು ಅವರಿಗೆ ಸಹಾಯ ಮಾಡುತ್ತೇವೆ.',
      'challenges_title' => 'ವ್ಯಾಪಾರದ ಸಾಮಾನ್ಯ ಸವಾಲುಗಳು',
      'challenges_sub' => 'ಈ ಅಂತರಗಳು ವೇಗವನ್ನು ನಿಧಾನಗೊಳಿಸುತ್ತದೆ ಮತ್ತು ಬೆಳವಣಿಗೆಯನ್ನು ಉಳಿಸಿಕೊಳ್ಳಲು ಕಷ್ಟವಾಗುತ್ತದೆ.',
      'ch1_t' => 'ತಂಡದ ನಿರ್ವಹಣೆ',
      'ch1_d' => 'ವಿಶ್ವಾಸಾರ್ಹ ಆನ್-ಗ್ರೌಂಡ್ ತಂಡಗಳನ್ನು ನಿರ್ಮಿಸಲು ಮತ್ತು ನಿರ್ವಹಿಸುವಲ್ಲಿ ತೊಂದರೆ.',
      'ch2_t' => 'ಅಸಮಂಜಸವಾದ ಮರಣದಂಡನೆ',
      'ch2_d' => 'ವಿವಿಧ ನಗರಗಳು ಅಥವಾ ಪ್ರದೇಶಗಳಲ್ಲಿ ಅಸಮಂಜಸವಾದ ಮರಣದಂಡನೆ.',
      'ch3_t' => 'ಸೀಮಿತ ಗೋಚರತೆ',
      'ch3_d' => 'ಮಾರಾಟದ ಕಾರ್ಯಕ್ಷಮತೆ ಮತ್ತು ಕ್ಷೇತ್ರ ಕಾರ್ಯಾಚರಣೆಗಳಲ್ಲಿ ಸೀಮಿತ ಗೋಚರತೆ.',
      'ch4_t' => 'ಕಾರ್ಯಾಚರಣೆಯ ವಿಳಂಬಗಳು',
      'ch4_d' => 'ವ್ಯಾಪಾರಿ ಆನ್‌ಬೋರ್ಡಿಂಗ್, ಗ್ರಾಹಕರ ಸ್ವಾಧೀನ ಅಥವಾ ಸಂಗ್ರಹಣೆಗಳಲ್ಲಿ ವಿಳಂಬ.',
      'ch5_t' => 'ಪ್ರಭಾವವನ್ನು ಅಳೆಯುವುದು',
      'ch5_d' => 'ಅಳೆಯಬಹುದಾದ ಪ್ರಭಾವದೊಂದಿಗೆ ದೊಡ್ಡ ಪ್ರಮಾಣದ ಪ್ರಚಾರಗಳನ್ನು ನಡೆಸುವಲ್ಲಿನ ಸವಾಲುಗಳು.',
      'support_title' => 'ನಿಮ್ಮ ವ್ಯಾಪಾರವನ್ನು ನಾವು ಹೇಗೆ ಬೆಂಬಲಿಸುತ್ತೇವೆ',
