      'svc1_t' => 'ಮಾರಾಟ ಮತ್ತು ಬೆಳವಣಿಗೆಯ ಪರಿಹಾರಗಳು',
      'svc1_d' => 'ಫಿನ್‌ಟೆಕ್, ಬಿಎಫ್‌ಎಸ್‌ಐ ಮತ್ತು ಸಾಲದಾದ್ಯಂತ ವ್ಯಾಪಾರಿ ಆನ್‌ಬೋರ್ಡಿಂಗ್, ಪ್ರಮುಖ ಉತ್ಪಾದನೆ ಮತ್ತು ಪರಿವರ್ತನೆಗಳನ್ನು ಬೆಂಬಲಿಸುವ ರಚನಾತ್ಮಕ ಮಾರಾಟ ಕಾರ್ಯಗತಗೊಳಿಸುವಿಕೆ.',
