      'svc2_d' => 'ಗ್ರಾಹಕರನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು, ಅವಕಾಶಗಳನ್ನು ಮೌಲ್ಯೀಕರಿಸಲು ಮತ್ತು ನಿರ್ಧಾರಗಳನ್ನು ತೆಗೆದುಕೊಳ್ಳಲು ವ್ಯಾಪಾರಗಳಿಗೆ ಸಹಾಯ ಮಾಡುವ ಆನ್-ಗ್ರೌಂಡ್ ಡೇಟಾ ಸಂಗ್ರಹಣೆ ಮತ್ತು ಮಾರುಕಟ್ಟೆ ಒಳನೋಟಗಳು.',
      'svc3_t' => 'ಸಿಬ್ಬಂದಿ ಪರಿಹಾರಗಳು',
      'svc3_d' => 'ಮಾರಾಟ, ಕಾರ್ಯಾಚರಣೆಗಳು ಮತ್ತು ವ್ಯಾಪಾರ ವಿಸ್ತರಣೆಯನ್ನು ಬೆಂಬಲಿಸಲು ಉದ್ಯಮಗಳಾದ್ಯಂತ ತರಬೇತಿ ಪಡೆದ, ಸ್ಕೇಲೆಬಲ್ ಮಾನವಶಕ್ತಿಯ ನಿಯೋಜನೆ.',
