      'step2_t' => 'ನಿಯೋಜಿಸಿ',
      'step2_d' => 'ತರಬೇತಿ ಪಡೆದ ತಂಡಗಳು, ಪರಿಕರಗಳು ಮತ್ತು ಕೆಲಸದ ಹರಿವುಗಳನ್ನು ನಿಮ್ಮ ಉದ್ದೇಶಗಳಿಗೆ ಹೊಂದಿಸಿದ್ದೇವೆ.',
      'step3_t' => 'ಕಾರ್ಯಗತಗೊಳಿಸಿ',
