      'faq_sub' => 'ഈ വിഷയത്തെക്കുറിച്ചുള്ള ദ്രുത ഉത്തരങ്ങൾ',
      'previous' => 'മുമ്പത്തെ',
      'next' => 'അടുത്തത്',
      'read_article' => 'ലേഖനം വായിക്കുക',
      'all_category_posts' => 'എല്ലാ {category} പോസ്റ്റുകളും',
      'more_from' => 'ഇതിൽ നിന്ന് കൂടുതൽ',
      'read_more_about' => '{title}-നെ കുറിച്ച് കൂടുതൽ വായിക്കുക',
      'view_category_articles' => 'എല്ലാ {category} ലേഖനങ്ങളും കാണുക',
      'browse_tagged' => '{tag} ടാഗ് ചെയ്ത ലേഖനങ്ങൾ ബ്രൗസ് ചെയ്യുക',
    ),
    'partner-with-us' => 
    array (
      'hero_title' => 'ഞങ്ങളോടൊപ്പം പങ്കാളി',
      'hero_desc' => 'യഥാർത്ഥ പ്രോജക്ടുകൾക്കൊപ്പം വളരാൻ തയ്യാറുള്ള വ്യക്തികൾക്കും ടീമുകൾക്കുമായി നിർമ്മിച്ച അവസരങ്ങൾ.',
      'hero_btn' => 'പ്രോജക്റ്റുകളിലെ ജോലിക്ക് അപേക്ഷിക്കുക',
      'intro_p1' => 'ബിസാനി ബ്രദേഴ്‌സിൽ, വ്യക്തികൾക്കും ഏജൻസികൾക്കും ടീമുകൾക്കും ഇന്ത്യയിലുടനീളമുള്ള വലിയ തോതിലുള്ള ബിസിനസ്സ് എക്‌സിക്യൂഷൻ പ്രോജക്‌ടുകളിൽ പങ്കെടുക്കുന്നതിന് ഞങ്ങൾ ഘടനാപരമായ തൊഴിൽ അവസരങ്ങൾ സൃഷ്ടിക്കുന്നു.',
      'intro_p2' => 'നിങ്ങളൊരു സ്വതന്ത്ര പ്രൊഫഷണലോ ഓൺ-ഗ്രൗണ്ട് വർക്ക്ഫോഴ്‌സുള്ള ഒരു സ്ഥാപനമോ ആകട്ടെ, ഞങ്ങൾ സ്ഥിരമായ പ്രോജക്ടുകളിലേക്കും വ്യക്തമായ പ്രക്രിയകളിലേക്കും വിശ്വസനീയമായ ഇടപഴകലുകളിലേക്കും ആക്‌സസ് വാഗ്ദാനം ചെയ്യുന്നു - വിപുലീകരിക്കുന്ന ബിസിനസുകൾക്കൊപ്പം സമ്പാദിക്കാനും പഠിക്കാനും വളരാനും നിങ്ങളെ പ്രാപ്‌തമാക്കുന്നു.',
      'intro_p3' => 'ഞങ്ങളുമായി ഇതിനകം ബന്ധമുള്ള 2,100+ ആളുകൾ ഉള്ളതിനാൽ, ഞങ്ങളുടെ നെറ്റ്‌വർക്ക് വിശ്വാസം, നിർവ്വഹണം, ദീർഘകാല സഹകരണം എന്നിവയിൽ നിർമ്മിച്ചതാണ്.',
      'opp_title' => 'നിങ്ങൾക്ക് പ്രവർത്തിക്കാൻ കഴിയുന്ന അവസരങ്ങൾ',
      'opp_subtitle' => 'ഇനിപ്പറയുന്നവ ഉൾപ്പെടെ, ഗ്രൗണ്ട്, ഫീൽഡ് എക്‌സിക്യൂഷൻ പ്രോജക്‌റ്റുകളുടെ വിശാലമായ ശ്രേണിയിലുടനീളം ഞങ്ങൾ പങ്കാളികളുമായി ഇടപഴകുന്നു:',
      'opp1' => 'വിൽപ്പന, വ്യാപാരി ഓൺബോർഡിംഗ് സംരംഭങ്ങൾ',
      'opp2' => 'മാർക്കറ്റ് സർവേകൾ, ഓഡിറ്റുകൾ, ഉപഭോക്തൃ പരിശോധന',
      'opp3' => 'ഫീൽഡ് ആക്റ്റിവേഷനും ബ്രാൻഡ് ഔട്ട്റീച്ച് പ്രോഗ്രാമുകളും',
      'opp4' => 'വായ്പാ പിന്തുണ, ഡോക്യുമെൻ്റേഷൻ, ശേഖരണ സഹായം',
      'opp5' => 'ടെറിട്ടറി വിപുലീകരണവും പൈലറ്റ് മാർക്കറ്റ് പ്രോജക്ടുകളും',
      'opp_closing' => 'മേഖല, സ്കെയിൽ, ദൈർഘ്യം എന്നിവ അനുസരിച്ച് അവസരങ്ങൾ വ്യത്യാസപ്പെടുന്നു - വ്യക്തികളെയും ഏജൻസികളെയും അവരുടെ ശേഷിക്ക് അനുസൃതമായി ജോലി കണ്ടെത്താൻ അനുവദിക്കുന്നു.',
      'offer_title' => 'ഞങ്ങളുടെ പങ്കാളികൾക്ക് ഞങ്ങൾ എന്താണ് വാഗ്ദാനം ചെയ്യുന്നത്',
      'offer1_t' => 'സ്ഥിരമായ പദ്ധതികളിലേക്കുള്ള പ്രവേശനം',
      'offer1_d' => 'എക്‌സിക്യൂഷൻ-ലെഡ് അസൈൻമെൻ്റുകളുടെ സ്ഥിരമായ പൈപ്പ്‌ലൈൻ സൃഷ്‌ടിച്ച്, മേഖലകളിലുടനീളമുള്ള സ്ഥാപിത ബിസിനസുകളുമായി ഞങ്ങൾ പ്രവർത്തിക്കുന്നു.',
      'offer2_t' => 'ഘടനാപരമായ തൊഴിൽ അന്തരീക്ഷം',
      'offer2_d' => 'വ്യക്തമായ സ്കോപ്പുകൾ, നിർവചിക്കപ്പെട്ട പ്രക്രിയകൾ, നിർവ്വഹണ മാർഗ്ഗനിർദ്ദേശങ്ങൾ എന്നിവ ഒരു പ്രോജക്റ്റിൽ എന്താണ് പ്രതീക്ഷിക്കുന്നതെന്ന് നിങ്ങൾക്ക് എല്ലായ്പ്പോഴും അറിയാമെന്ന് ഉറപ്പാക്കുന്നു.',
      'offer3_t' => 'പരിശീലനവും ഗ്രൗണ്ട് സപ്പോർട്ടും',
      'offer3_d' => 'പ്രോജക്റ്റ് നിർവ്വഹണത്തിന് മുമ്പും സമയത്തും ആവശ്യമായ പരിശീലനം, ഉപകരണങ്ങൾ, മാർഗ്ഗനിർദ്ദേശം എന്നിവ ഞങ്ങൾ നിങ്ങളെ സജ്ജമാക്കുന്നു.',
      'offer4_t' => 'ഇൻക്ലൂസീവ് ഓപ്പർച്യുണിറ്റി പ്ലാറ്റ്ഫോം',
      'offer4_d' => 'ലിംഗഭേദം, പശ്ചാത്തലം അല്ലെങ്കിൽ മുൻകാല വിൽപ്പന അനുഭവം എന്നിവയെ അടിസ്ഥാനമാക്കിയുള്ള നിയന്ത്രണങ്ങളൊന്നുമില്ല.',
      'offer5_t' => 'പ്രകടനം-ലിങ്ക്ഡ് വരുമാനം',
      'offer5_d' => 'നിങ്ങളുടെ വരുമാനം നിർവ്വഹണവും ഫലങ്ങളും, പ്രതിഫലദായകമായ സ്ഥിരത, പ്രതിബദ്ധത എന്നിവയുമായി ബന്ധപ്പെട്ടിരിക്കുന്നു.',
      'offer6_t' => 'വിശ്വസനീയമായ പ്രതിമാസ പേഔട്ടുകൾ',
      'offer6_d' => 'എല്ലാ പേഔട്ടുകളും സുതാര്യമായ പ്രതിമാസ സൈക്കിൾ പിന്തുടരുന്നു, ഇത് ആത്മവിശ്വാസത്തോടെ ധനകാര്യങ്ങൾ ആസൂത്രണം ചെയ്യാനും നിയന്ത്രിക്കാനും നിങ്ങളെ സഹായിക്കുന്നു.',
      'trust_title' => 'എന്തുകൊണ്ടാണ് ആളുകൾ ഞങ്ങളോടൊപ്പം പ്രവർത്തിക്കുന്നത് വിശ്വസിക്കുന്നത്',
      'trust1_d' => 'പദ്ധതികളിൽ ഉടനീളം ഏർപ്പെട്ടിരിക്കുന്ന വ്യക്തികൾ',
      'trust2_n' => 'തെളിയിച്ചു',
      'trust2_d' => 'വലിയ, വിതരണം ചെയ്ത ഫീൽഡ് ടീമുകൾ കൈകാര്യം ചെയ്യുന്ന അനുഭവം',
      'trust3_n' => 'ക്ലിയർ',
      'trust3_d' => 'ആശയവിനിമയവും ഘടനാപരമായ നിർവ്വഹണ മോഡലുകളും',
      'trust4_n' => 'ദീർഘകാല',
      'trust4_d' => 'സഹകരണ മനോഭാവം, ഒറ്റത്തവണ അസൈൻമെൻ്റുകളല്ല',
      'voices_title' => 'വയലിൽ നിന്നുള്ള ശബ്ദങ്ങൾ',
      'apply_title' => 'പ്രോജക്റ്റുകളിലെ ജോലിക്ക് അപേക്ഷിക്കുക',
      'apply_subtitle' => 'ഞങ്ങളുടെ നെറ്റ്‌വർക്കിൽ ചേരുന്നതിന് ചുവടെ നിങ്ങളുടെ വിശദാംശങ്ങൾ പൂരിപ്പിക്കുക.',
      'form_partner_type' => 'ഞാൻ ഒരു...',
      'form_select' => 'ഓപ്ഷൻ തിരഞ്ഞെടുക്കുക',
      'form_individual' => 'വ്യക്തിഗത പ്രൊഫഷണൽ',
      'form_agency' => 'ഏജൻസി / ടീം ലീഡ്',
      'form_message_opt' => 'സന്ദേശം (ഓപ്ഷണൽ)',
      'form_apply' => 'ഇപ്പോൾ പ്രയോഗിക്കുക',
      'success_title' => 'അപേക്ഷ ലഭിച്ചു!',
      'success_desc' => 'ഞങ്ങളുടെ വളർച്ചാ പങ്കാളികളുടെ പട്ടികയിൽ നിങ്ങളുടെ വിശദാംശങ്ങൾ ഞങ്ങൾക്ക് ലഭിച്ചു.',
    ),
    'why-work-with-us' => 
    array (
      'hero_h1_a' => 'എക്സിക്യൂഷൻ അത്',
      'hero_h1_b' => 'ബിസിനസുകൾക്ക് ആശ്രയിക്കാം.',
      'hero_desc' => 'ഘടനാപരമായ ടീമുകൾ, അച്ചടക്കമുള്ള പ്രക്രിയകൾ, സ്ഥിരമായ ഫലങ്ങൾ നൽകുന്ന ഓൺ-ഗ്രൗണ്ട് എക്‌സിക്യൂഷൻ എന്നിവയുള്ള ബിസിനസുകളെ ഞങ്ങൾ പിന്തുണയ്ക്കുന്നു.',
      'hero_btn' => 'ഞങ്ങളുടെ ടീമുമായി സംസാരിക്കുക',
      'scale_title' => 'എക്സിക്യൂഷൻ വഴി സ്കെയിലിംഗ് പരിമിതപ്പെടുത്തിയിരിക്കുന്നു.',
      'scale_p1' => 'ഒരു ബിസിനസ്സ് സ്കെയിൽ ചെയ്യുന്നത് ആശയങ്ങളാൽ അപൂർവ്വമായി പരിമിതപ്പെടുത്തിയിരിക്കുന്നു - അത് നടപ്പിലാക്കുന്നതിലൂടെ പരിമിതപ്പെടുത്തിയിരിക്കുന്നു. പ്രദേശങ്ങൾ, ഉൽപ്പന്നങ്ങൾ, ഉപഭോക്തൃ വിഭാഗങ്ങൾ എന്നിവയിലുടനീളം ബിസിനസുകൾ വികസിക്കുമ്പോൾ, വിൽപ്പന, ആളുകൾ, ഓൺ-ഗ്രൗണ്ട് പ്രവർത്തനങ്ങൾ എന്നിവ കൈകാര്യം ചെയ്യുന്നത് കൂടുതൽ സങ്കീർണ്ണമാകുന്നു.',
      'scale_p2' => 'ബിസാനി ബ്രദേഴ്സിൽ, നിർവ്വഹണത്തിൻ്റെ ഉടമസ്ഥാവകാശം ഏറ്റെടുക്കാൻ ഞങ്ങൾ ഓർഗനൈസേഷനുകളുമായി പങ്കാളികളാകുന്നു - അവിടെയെത്താൻ ആവശ്യമായ ടീമുകളും പ്രക്രിയകളും ഡെലിവറിയും ഞങ്ങൾ നിയന്ത്രിക്കുമ്പോൾ വളർച്ചയിൽ ശ്രദ്ധ കേന്ദ്രീകരിക്കാൻ അവരെ സഹായിക്കുന്നു.',
      'challenges_title' => 'ബിസിനസ്സ് നേരിടുന്ന പൊതുവായ വെല്ലുവിളികൾ',
      'challenges_sub' => 'ഈ വിടവുകൾ വേഗത കുറയ്ക്കുകയും വളർച്ച നിലനിർത്താൻ പ്രയാസമാക്കുകയും ചെയ്യുന്നു.',
      'ch1_t' => 'ടീം മാനേജ്മെൻ്റ്',
      'ch1_d' => 'വിശ്വസനീയമായ ഓൺ-ഗ്രൗണ്ട് ടീമുകളെ നിർമ്മിക്കുന്നതിനും നിയന്ത്രിക്കുന്നതിനും ബുദ്ധിമുട്ട്.',
      'ch2_t' => 'പൊരുത്തമില്ലാത്ത നിർവ്വഹണം',
      'ch2_d' => 'വ്യത്യസ്ത നഗരങ്ങളിലോ പ്രദേശങ്ങളിലോ ഉടനീളം അസ്ഥിരമായ നിർവ്വഹണം.',
      'ch3_t' => 'പരിമിതമായ ദൃശ്യപരത',
      'ch3_d' => 'വിൽപ്പന പ്രകടനത്തിലേക്കും ഫീൽഡ് പ്രവർത്തനങ്ങളിലേക്കും പരിമിതമായ ദൃശ്യപരത.',
      'ch4_t' => 'പ്രവർത്തന കാലതാമസം',
      'ch4_d' => 'മർച്ചൻ്റ് ഓൺബോർഡിംഗ്, ഉപഭോക്തൃ ഏറ്റെടുക്കൽ അല്ലെങ്കിൽ ശേഖരണങ്ങൾ എന്നിവയിലെ കാലതാമസം.',
      'ch5_t' => 'ആഘാതം അളക്കുന്നു',
      'ch5_d' => 'വലിയ തോതിലുള്ള കാമ്പെയ്‌നുകൾ അളക്കാവുന്ന സ്വാധീനം ചെലുത്തുന്നതിലുള്ള വെല്ലുവിളികൾ.',
      'support_title' => 'നിങ്ങളുടെ ബിസിനസിനെ ഞങ്ങൾ എങ്ങനെ പിന്തുണയ്ക്കുന്നു',
      'support_sub' => 'സ്വതന്ത്രമായോ ഒന്നിച്ചോ പ്രവർത്തിക്കാൻ രൂപകൽപ്പന ചെയ്തിട്ടുള്ള സംയോജിത നിർവ്വഹണ പിന്തുണ.',
      'svc1_t' => 'വിൽപ്പന & വളർച്ചാ പരിഹാരങ്ങൾ',
      'svc1_d' => 'ഫിൻടെക്, ബിഎഫ്എസ്ഐ, വായ്പ എന്നിവയിലുടനീളം മർച്ചൻ്റ് ഓൺബോർഡിംഗ്, ലീഡ് ജനറേഷൻ, പരിവർത്തനങ്ങൾ എന്നിവയെ പിന്തുണയ്ക്കുന്ന ഘടനാപരമായ വിൽപ്പന നിർവ്വഹണം.',
      'svc_link' => 'പരിഹാരം പര്യവേക്ഷണം ചെയ്യുക',
      'svc2_t' => 'സർവേ & മാർക്കറ്റ് റിസർച്ച്',
      'svc2_d' => 'ഉപഭോക്താക്കളെ മനസ്സിലാക്കാനും അവസരങ്ങൾ സാധൂകരിക്കാനും തീരുമാനങ്ങൾ എടുക്കാനും ബിസിനസുകളെ സഹായിക്കുന്ന ഗ്രൗണ്ട് ഡാറ്റാ ശേഖരണവും വിപണി സ്ഥിതിവിവരക്കണക്കുകളും.',
      'svc3_t' => 'സ്റ്റാഫ് പരിഹാരങ്ങൾ',
      'svc3_d' => 'വിൽപന, പ്രവർത്തനങ്ങൾ, ബിസിനസ് വിപുലീകരണം എന്നിവയെ പിന്തുണയ്‌ക്കുന്നതിന് വ്യവസായങ്ങളിലുടനീളം പരിശീലനം സിദ്ധിച്ചതും അളക്കാവുന്നതുമായ മനുഷ്യശക്തിയുടെ വിന്യാസം.',
      'svc4_t' => 'BTL & ATL സജീവമാക്കൽ',
      'svc4_d' => 'ദൃശ്യപരത വർദ്ധിപ്പിക്കുന്നതിനായി രൂപകൽപ്പന ചെയ്‌തിരിക്കുന്ന ബ്രാൻഡ് ആക്ടിവേഷനുകൾ, ഉൽപ്പന്ന ലോഞ്ചുകൾ, പ്രൊമോഷണൽ കാമ്പെയ്‌നുകൾ എന്നിവയുടെ അവസാനം മുതൽ അവസാനം വരെ നടപ്പിലാക്കൽ.',
      'svc5_t' => 'വായ്പയും ശേഖരണവും',
      'svc5_d' => 'കാര്യക്ഷമതയും വിശ്വാസവും ഉറപ്പാക്കുന്ന, വിൽപ്പനയ്ക്കും അനുസരണമുള്ള ശേഖരണത്തിനും വായ്പ നൽകുന്നതിന് സമർപ്പിത ടീമുകളും കോൾ സെൻ്റർ പിന്തുണയും.',
      'work_title' => 'ഞങ്ങൾ ഉപഭോക്താക്കളുമായി എങ്ങനെ പ്രവർത്തിക്കുന്നു',
