      'intro_p2' => 'ଆପଣ ଏକ ସ୍ independent ାଧୀନ ବୃତ୍ତିଗତ କିମ୍ବା ଏକ ଅନ୍-ଗ୍ରାଉଣ୍ଡ୍ ୱାର୍କଫୋର୍ସ ସହିତ ଏକ ସଂସ୍ଥା, ଆମେ ସ୍ଥିର ପ୍ରୋଜେକ୍ଟ, ସ୍ୱଚ୍ଛ ପ୍ରକ୍ରିୟା ଏବଂ ନିର୍ଭରଯୋଗ୍ୟ ଯୋଗଦାନକୁ ପ୍ରବେଶ ପ୍ରଦାନ କରୁଛୁ - ବ୍ୟବସାୟ ବିସ୍ତାର କରିବା ସହିତ ଆପଣଙ୍କୁ ରୋଜଗାର, ଶିଖିବା ଏବଂ ବ grow ାଇବାରେ ସକ୍ଷମ କରେ |',
      'intro_p3' => '2,100+ ଲୋକ ଆମ ସହିତ ଜଡିତ ହୋଇସାରିଛନ୍ତି, ଆମର ନେଟୱାର୍କ ବିଶ୍ୱାସ, କାର୍ଯ୍ୟକାରିତା ଏବଂ ଦୀର୍ଘକାଳୀନ ସହଯୋଗ ଉପରେ ନିର୍ମିତ |',
